निम्नलिखित C कोड का आउटपुट क्या होगा?

#include <stdio.h>
int main() {
    int x = 5;
    printf("%d %d %d", x, x++, ++x);
    return 0;
}

निम्नलिखित C++ कोड का आउटपुट क्या होगा?

#include <iostream>
using namespace std;
int main() {
    int a = 10;
    int &ref = a;
    ref = 25;
    cout << a;
    return 0;
}

निम्नलिखित C++ कोड का आउटपुट क्या होगा?

#include <iostream>
using namespace std;
class Base {
public:
    virtual void show() { cout << "Base "; }
};
class Derived : public Base {
public:
    void show() { cout << "Derived "; }
};
int main() {
    Base *b = new Derived();
    b->show();
    return 0;
}
